HTML = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>AnviRoute</title><style>
*{box-sizing:border-box}body{margin:0;background:#0c1220;color:#e6edf8;font:15px system-ui}main{max-width:1080px;margin:auto;padding:36px 24px}h1{font-size:32px;margin:0}h1 span{color:#64e8c7}p,small{color:#9baec8}header{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.badge{border:1px solid #34516b;padding:8px 14px;border-radius:20px;color:#64e8c7}.grid{display:grid;grid-template-columns:1fr 1fr;gap:20px}.card{background:#141e30;border:1px solid #28364d;border-radius:14px;padding:22px;margin-bottom:20px}h2{font-size:17px;margin:0 0 16px}input,select,button{font:inherit;border-radius:7px;padding:10px;border:1px solid #354862}input,select{background:#0b1526;color:inherit;width:100%;margin:5px 0 12px}label{font-size:13px;color:#adc0d7}button{cursor:pointer;background:#64e8c7;color:#09241d;font-weight:600;margin:3px 5px 3px 0}button.secondary{background:#24334c;color:#dce8f6}code{color:#64e8c7;overflow-wrap:anywhere}.row{padding:12px 0;border-bottom:1px solid #29384c}.ok{color:#64e8c7}.bad{color:#ff9b9b}#notice{min-height:24px;white-space:pre-wrap}#events{max-height:320px;overflow:auto;font-size:13px}.flow{display:flex;gap:12px;justify-content:space-between;flex-wrap:wrap}.flow div{background:#0c1526;padding:14px;border-radius:9px;flex:1;min-width:190px}.flow small{display:block;margin-top:6px}a{color:#64e8c7}@media(max-width:760px){.grid{grid-template-columns:1fr}header{align-items:start;gap:15px}}
</style></head><body><main><header><div><h1>Anvi<span>Route</span></h1><p>Your local routing desk</p></div><div class="badge">Local service · <span id="version"></span></div></header>
<div class="card"><h2>Connection path</h2><div class="flow"><div>Claude Code → AnviRoute<small id="client">Waiting for Claude</small></div><div>AnviRoute adapter<small id="adapter">Listening locally</small></div><div>AnviRoute → API / Kaggle<small id="upstream">Not checked</small></div></div><p>Second terminal, inside your project: <code>anviroute.cmd run claude</code></p></div>
<div class="grid"><section><div class="card"><h2>API connections</h2><div id="providers"></div></div><div class="card"><h2>Add or edit a connection</h2><form id="form"><input id="id" type="hidden"><label>Name<input id="name" required placeholder="Kaggle Qwen"></label><label>API URL<input id="url" required placeholder="https://your-session.trycloudflare.com/v1"></label><label>API key<input id="key" type="password" autocomplete="off" placeholder="Blank keeps existing key when editing"></label><label>API format<select id="format"><option value="openai">OpenAI-compatible / Ollama</option><option value="anthropic">Anthropic Messages</option></select></label><label>Model (optional)<input id="model" placeholder="Leave blank to detect automatically"></label><button>Save connection</button><button type="button" class="secondary" id="clear">New connection</button></form><small>API keys stay in this service's memory. Enter them again after restarting it. URLs and model choices are saved.</small></div></section>
<section><div class="card"><h2>Selected model</h2><p id="active">Select a connection</p><button id="check">Check API and model</button><button id="discover" class="secondary">Refresh models</button><select id="models"><option>No models loaded</option></select><button id="choose" class="secondary">Use selected model</button><p id="notice" role="status"></p></div><div class="card"><h2>Diagnostics</h2><small>No prompts, replies, or API keys are recorded.</small><div id="events"></div></div></section></div></main><script>
const token=__TOKEN__;let state={providers:[]};const $=id=>document.getElementById(id);function msg(t,bad=false){$('notice').textContent=t;$('notice').className=bad?'bad':'ok'}
async function api(path,data){let r=await fetch('/control/'+path,{method:data?'POST':'GET',headers:{Authorization:'Bearer '+token,'Content-Type':'application/json'},body:data?JSON.stringify(data):undefined});let j=await r.json();if(!r.ok)throw Error(j.error||'Request failed');return j}
function button(label,action){let b=document.createElement('button');b.textContent=label;b.className='secondary';b.onclick=()=>action().catch(e=>msg(e.message,true));return b}
async function refresh(){try{state=await api('status');$('version').textContent=state.version;$('client').textContent=state.client_seen?'Request received · '+state.client_seen:'Waiting for Claude';$('adapter').textContent=state.address;$('upstream').textContent=state.upstream||'Not checked';let a=state.providers.find(p=>p.id===state.active);$('active').textContent=a?a.name+' · '+(a.model||'Model not selected'):'Select a connection';$('providers').replaceChildren();for(let p of state.providers){let r=document.createElement('div');r.className='row';let t=document.createElement('p');t.textContent=(p.id===state.active?'● ':'')+p.name+' · '+(p.model||'Auto-detect');r.append(t,button('Activate',async()=>{await api('activate',{id:p.id});await refresh()}),button('Edit',async()=>{for(let k of ['id','name','url','model'])$(k).value=p[k]||'';$('format').value=p.format;$('key').value=''}),button('Remove',async()=>{if(confirm('Remove '+p.name+'?')){await api('remove',{id:p.id});await refresh()}}));$('providers').append(r)}$('events').replaceChildren();for(let e of [...state.events].reverse()){let d=document.createElement('div');d.className='row '+(e.ok?'ok':'bad');d.textContent=e.time+' · '+e.stage+' · '+e.message;$('events').append(d)}}catch(e){msg(e.message,true)}}
$('form').onsubmit=async e=>{e.preventDefault();try{await api('save',{id:$('id').value,name:$('name').value,url:$('url').value,key:$('key').value,model:$('model').value,format:$('format').value});$('key').value='';msg('Saved. Activate the connection and check it.');await refresh()}catch(e){msg(e.message,true)}};
$('clear').onclick=()=>{$('form').reset();$('id').value=''};
$('check').onclick=async()=>{msg('Checking API and inference. A cold model may take time…');try{let r=await api('check',{});msg(r.message);await refresh()}catch(e){msg(e.message,true);await refresh()}};
$('discover').onclick=async()=>{try{let r=await api('models',{});$('models').replaceChildren();for(let m of r.models){let o=document.createElement('option');o.value=o.textContent=m;$('models').append(o)}msg('Models refreshed')}catch(e){msg(e.message,true)}};
$('choose').onclick=async()=>{try{await api('model',{model:$('models').value});msg('Model selected. New requests use it.');await refresh()}catch(e){msg(e.message,true)}};refresh();setInterval(refresh,4000);
</script></body></html>'''
